-- =============================================================================
-- schema.sql — all migrations concatenated, in order.
--
-- GENERATED by `npm run schema`. Edit the files in supabase/migrations/,
-- not this file.
--
-- Paste into the Supabase SQL editor and run once, on an empty project. The
-- final block stamps schema_migrations so a later `npm run migrate` skips them.
-- =============================================================================

-- >>>>>>>>>>>>>>>>>>>> 20260827000001_core_schema.sql <<<<<<<<<<<<<<<<<<<<
-- =============================================================================
-- 0001_core_schema.sql — reference, source-mirror and canonical layers
--
-- Layer 1 (reference)     brands, countries, sites, players, technologies
-- Layer 2 (source mirror) categories, products, variants, product_categories,
--                         product_content  — what the site literally says
-- Layer 3 (canonical)     product_lines, generations, models — what we derive
--
-- The split exists because storefronts model the same physical hierarchy
-- inconsistently. See docs/DESIGN.md §5.
-- =============================================================================

create extension if not exists "pgcrypto";     -- gen_random_uuid()
create extension if not exists "pg_trgm";      -- fuzzy name matching in normalize

-- =============================================================================
-- Enumerated domains. Kept as CHECK constraints rather than PG enums so that
-- adding a value is a migration, not an ALTER TYPE that locks readers.
-- =============================================================================

-- skill_tier      pro | performance | recreational | premium | junior | unknown
-- paddle_shape    elongated | hybrid | standard | widebody | unknown
-- attr_source     source_option | title | tag | collection | pdp | llm | manual
-- category_role   sport | assortment | skill_tier | generation | series
--                 | signature | sale | accessory | other

-- =============================================================================
-- Layer 1 — reference
-- =============================================================================

create table brands (
  id            uuid primary key default gen_random_uuid(),
  slug          text not null unique,               -- 'joola'
  name          text not null,                      -- 'JOOLA'
  created_at    timestamptz not null default now()
);

create table countries (
  code          text primary key,                   -- ISO-3166-1 alpha-2, 'US'
  name          text not null,
  currency      text not null                       -- ISO-4217 default, 'USD'
);

-- One row per (brand, country) storefront. This is the crawl target and the
-- unit that country expansion adds rows to.
create table sites (
  id                uuid primary key default gen_random_uuid(),
  brand_id          uuid not null references brands(id) on delete cascade,
  country_code      text not null references countries(code),
  base_url          text not null,                  -- 'https://joola.com'
  platform          text not null,                  -- 'shopify' | 'woocommerce' | 'custom'
  currency          text not null,
  locale            text not null default 'en-US',
  -- Which source collections make up the assortment we care about. Declared in
  -- config and mirrored here so a query can explain why a product was crawled.
  assortment_handles text[] not null default '{}',
  is_active         boolean not null default true,
  crawl_delay_ms    integer not null default 1200,  -- politeness; robots may raise it
  notes             text,
  created_at        timestamptz not null default now(),
  unique (brand_id, country_code, base_url)
);

-- Endorsing athletes. Colourways on this brand are named after players
-- ('Blaze Red (Ben Johns)'), which makes the player a real analytic dimension.
create table players (
  id            uuid primary key default gen_random_uuid(),
  brand_id      uuid references brands(id) on delete cascade,
  name          text not null,
  slug          text not null,
  created_at    timestamptz not null default now(),
  unique (brand_id, slug)
);

-- Brand technology dictionary ('Carbon Friction Surface', 'Propulsion Core').
create table technologies (
  id            uuid primary key default gen_random_uuid(),
  brand_id      uuid not null references brands(id) on delete cascade,
  name          text not null,
  slug          text not null,
  description   text,
  first_seen_at timestamptz not null default now(),
  unique (brand_id, slug)
);

-- =============================================================================
-- Layer 3 — canonical hierarchy (declared before layer 2 so products can FK to it)
--
--   product_line  Perseus
--   generation    Pro V
--   model         Perseus Pro V   (line × generation × optional sub-line 'Dual')
-- =============================================================================

create table product_lines (
  id            uuid primary key default gen_random_uuid(),
  brand_id      uuid not null references brands(id) on delete cascade,
  slug          text not null,                      -- 'perseus'
  name          text not null,                      -- 'Perseus'
  description   text,
  created_at    timestamptz not null default now(),
  unique (brand_id, slug)
);

create table generations (
  id            uuid primary key default gen_random_uuid(),
  brand_id      uuid not null references brands(id) on delete cascade,
  slug          text not null,                      -- 'pro-v'
  name          text not null,                      -- 'Pro V'
  -- Ordering for "which version is newer". Gen 1 = 1, Pro IV = 4, Pro V = 5.
  sequence      integer,
  released_at   date,
  created_at    timestamptz not null default now(),
  unique (brand_id, slug)
);

create table models (
  id                uuid primary key default gen_random_uuid(),
  brand_id          uuid not null references brands(id) on delete cascade,
  product_line_id   uuid references product_lines(id) on delete set null,
  generation_id     uuid references generations(id) on delete set null,
  sub_line          text,                           -- 'Dual', 'CFS', NULL
  slug              text not null,                  -- 'perseus-pro-v'
  name              text not null,                  -- 'Perseus Pro V'
  skill_tier        text not null default 'unknown'
                    check (skill_tier in ('pro','performance','recreational',
                                          'premium','junior','unknown')),
  shape             text not null default 'unknown'
                    check (shape in ('elongated','hybrid','standard',
                                     'widebody','unknown')),
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now(),
  unique (brand_id, slug)
);

create index models_line_idx on models(product_line_id);
create index models_generation_idx on models(generation_id);
create index models_skill_tier_idx on models(skill_tier);

-- =============================================================================
-- Layer 2 — source mirror
-- =============================================================================

-- Collections / menu nodes as published by the site. Self-referencing so the
-- mega-menu tree survives intact; `nav_path` carries the human breadcrumb.
create table categories (
  id                  uuid primary key default gen_random_uuid(),
  site_id             uuid not null references sites(id) on delete cascade,
  source_category_id  text not null,                -- Shopify collection id
  handle              text not null,                -- 'professional-pickleball-paddles'
  title               text not null,                -- 'Pro'
  description         text,
  url                 text,
  parent_id           uuid references categories(id) on delete set null,
  depth               integer not null default 0,
  nav_path            text[] not null default '{}', -- {'Pickleball','Paddles','Pro'}
  -- Derived: what this collection *means*. Drives the UI's facet grouping.
  category_role       text not null default 'other'
                      check (category_role in ('sport','assortment','skill_tier',
                             'generation','series','signature','sale','accessory','other')),
  position            integer,
  in_main_nav         boolean not null default false,
  product_count       integer not null default 0,
  first_seen_at       timestamptz not null default now(),
  last_seen_at        timestamptz not null default now(),
  is_active           boolean not null default true,
  unique (site_id, source_category_id)
);

create index categories_site_role_idx on categories(site_id, category_role);
create index categories_handle_idx on categories(site_id, handle);

-- One row per product per site. The same physical paddle sold in the US and in
-- Australia is two rows; that is intentional.
create table products (
  id                  uuid primary key default gen_random_uuid(),
  site_id             uuid not null references sites(id) on delete cascade,
  model_id            uuid references models(id) on delete set null,  -- resolved in normalize
  source_product_id   text not null,
  handle              text not null,
  title               text not null,
  vendor              text,
  product_type        text,
  tags                text[] not null default '{}',
  body_html           text,
  url                 text,
  image_url           text,
  published_at        timestamptz,
  source_created_at   timestamptz,
  source_updated_at   timestamptz,
  -- Assortment gate. Accessories and apparel slip into collections; this is the
  -- flag every analytic query filters on.
  is_in_assortment    boolean not null default true,
  first_seen_at       timestamptz not null default now(),
  last_seen_at        timestamptz not null default now(),
  is_active           boolean not null default true,
  unique (site_id, source_product_id)
);

create index products_site_idx on products(site_id);
create index products_model_idx on products(model_id);
create index products_handle_idx on products(site_id, handle);
create index products_tags_idx on products using gin(tags);
create index products_title_trgm_idx on products using gin(title gin_trgm_ops);

-- Membership changes over time — a product entering the 'Sale' collection is a
-- signal in its own right, so this carries first/last seen rather than being a
-- plain join table.
create table product_categories (
  product_id      uuid not null references products(id) on delete cascade,
  category_id     uuid not null references categories(id) on delete cascade,
  position        integer,
  first_seen_at   timestamptz not null default now(),
  last_seen_at    timestamptz not null default now(),
  is_active       boolean not null default true,
  primary key (product_id, category_id)
);

create index product_categories_category_idx on product_categories(category_id);

-- The SKU. Atomic unit of price/stock time series.
create table variants (
  id                  uuid primary key default gen_random_uuid(),
  product_id          uuid not null references products(id) on delete cascade,
  site_id             uuid not null references sites(id) on delete cascade,
  source_variant_id   text not null,
  sku                 text,
  barcode             text,
  title               text,                         -- '16mm / Blaze Red (Ben Johns)'
  position            integer,
  image_url           text,

  -- Raw option values exactly as the source gave them, so a normalization bug
  -- is always recoverable without a re-crawl.
  option1_name        text,
  option1_value       text,
  option2_name        text,
  option2_value       text,
  option3_name        text,
  option3_value       text,

  -- ---- derived attributes (normalize stage) --------------------------------
  -- These are the answer to "what sizes / colours / versions exist". They are
  -- populated from option values, product title, tags, collections or the PDP,
  -- whichever wins; attr_source records which, per docs/DESIGN.md §3.
  core_thickness_mm   numeric(4,1),                 -- 14.0 | 16.0
  colorway            text,                         -- 'Blaze Red'
  color_primary       text,
  color_secondary     text,
  endorsed_player_id  uuid references players(id) on delete set null,
  weight_grams        numeric(6,2),
  grip_length_mm      numeric(5,1),
  paddle_length_mm    numeric(5,1),
  paddle_width_mm     numeric(5,1),
  shape               text check (shape in ('elongated','hybrid','standard',
                                            'widebody','unknown')),
  attr_source         jsonb not null default '{}'::jsonb,  -- {"core_thickness_mm":"title"}
  attr_confidence     numeric(3,2),                 -- 0.00–1.00, lowest across attrs

  -- Long-tail specs that do not deserve a column.
  attributes          jsonb not null default '{}'::jsonb,

  first_seen_at       timestamptz not null default now(),
  last_seen_at        timestamptz not null default now(),
  is_active           boolean not null default true,
  unique (site_id, source_variant_id)
);

create index variants_product_idx on variants(product_id);
create index variants_site_idx on variants(site_id);
create index variants_sku_idx on variants(sku);
create index variants_thickness_idx on variants(core_thickness_mm);
create index variants_player_idx on variants(endorsed_player_id);

-- PDP-derived content. Versioned by content_hash so re-crawls that changed
-- nothing do not create rows, but a genuine copy/spec change is preserved.
create table product_content (
  id              uuid primary key default gen_random_uuid(),
  product_id      uuid not null references products(id) on delete cascade,
  content_hash    varchar(64) not null,             -- sha256 of the normalised payload
  description     text,
  specs           jsonb not null default '{}'::jsonb,   -- {'Core':'16mm Polypropylene'}
  technologies    text[] not null default '{}',
  media           jsonb not null default '[]'::jsonb,
  breadcrumb      text[] not null default '{}',
  captured_at     timestamptz not null default now(),
  unique (product_id, content_hash)
);

create index product_content_product_idx on product_content(product_id, captured_at desc);

create table product_technologies (
  product_id      uuid not null references products(id) on delete cascade,
  technology_id   uuid not null references technologies(id) on delete cascade,
  primary key (product_id, technology_id)
);

-- =============================================================================
-- updated_at maintenance
-- =============================================================================

create or replace function touch_updated_at() returns trigger
language plpgsql as $$
begin
  new.updated_at = now();
  return new;
end;
$$;

create trigger models_touch before update on models
  for each row execute function touch_updated_at();

-- >>>>>>>>>>>>>>>>>>>> 20260827000002_timeseries.sql <<<<<<<<<<<<<<<<<<<<
-- =============================================================================
-- 0002_timeseries.sql — crawl runs and the price / discount / stock history
--
-- This is the reason the project exists. A catalogue scrape tells you what is
-- sold today; these tables tell you what changed and when.
--
-- Sizing: 116 variants/day for JOOLA US is ~42k snapshot rows/year. At 20
-- brands x 4 countries x 500 variants it is ~15M/year — the point at which
-- monthly partitioning of variant_snapshots becomes worthwhile. See §"scaling"
-- at the bottom.
-- =============================================================================

-- One row per crawl. Everything written by a run carries its run_id so a bad
-- run can be identified, explained, and excluded from charts.
create table crawl_runs (
  id                uuid primary key default gen_random_uuid(),
  site_id           uuid not null references sites(id) on delete cascade,
  run_type          text not null default 'scheduled'
                    check (run_type in ('scheduled','manual','backfill')),
  status            text not null default 'pending'
                    check (status in ('pending','running','done','partial','error')),
  -- Which stages were requested vs completed, for the pipeline-health panel.
  stages_requested  text[] not null default '{}',
  stages_done       text[] not null default '{}',
  categories_found  integer not null default 0,
  products_found    integer not null default 0,
  products_new      integer not null default 0,
  variants_found    integer not null default 0,
  variants_new      integer not null default 0,
  snapshots_written integer not null default 0,
  events_written    integer not null default 0,
  stats             jsonb not null default '{}'::jsonb,
  error_message     text,
  started_at        timestamptz not null default now(),
  finished_at       timestamptz,
  created_at        timestamptz not null default now()
);

create index crawl_runs_site_started_idx on crawl_runs(site_id, started_at desc);
create index crawl_runs_status_idx on crawl_runs(status);

create table crawl_errors (
  id              uuid primary key default gen_random_uuid(),
  run_id          uuid not null references crawl_runs(id) on delete cascade,
  stage           text not null,
  target          text,                              -- the URL/handle that failed
  error_type      text not null default 'stage_error'
                  check (error_type in ('http_error','parse_error','timeout',
                                        'stage_error','normalize_error','db_error')),
  error_message   text,
  status_code     integer,
  created_at      timestamptz not null default now()
);

create index crawl_errors_run_idx on crawl_errors(run_id);

-- =============================================================================
-- variant_snapshots — append-only. One row per variant per successful run.
--
-- observed_at is when WE LOOKED, not when the price changed. Charts must step-
-- interpolate between points, never linearly interpolate.
--
-- A failed run writes NO snapshots, so a site outage can never be mistaken for
-- a catalogue-wide stockout.
-- =============================================================================
create table variant_snapshots (
  id                  bigserial primary key,
  run_id              uuid not null references crawl_runs(id) on delete cascade,
  variant_id          uuid not null references variants(id) on delete cascade,
  site_id             uuid not null references sites(id) on delete cascade,
  observed_at         timestamptz not null default now(),

  price               numeric(12,2),
  compare_at_price    numeric(12,2),
  currency            text not null,

  -- Stored generated columns: "everything over 20% off on any past date"
  -- becomes an index scan instead of a scan-plus-arithmetic.
  is_on_sale          boolean generated always as (
                        compare_at_price is not null
                        and price is not null
                        and compare_at_price > price
                      ) stored,
  discount_pct        numeric(5,2) generated always as (
                        case
                          when compare_at_price is not null
                           and price is not null
                           and compare_at_price > 0
                           and compare_at_price > price
                          then round(((compare_at_price - price) / compare_at_price) * 100, 2)
                          else 0
                        end
                      ) stored,

  is_available        boolean,
  inventory_quantity  integer,                       -- null when not exposed
  -- Merchandising position within its primary collection. Movement here is an
  -- early signal of a push or a wind-down.
  position_in_category integer,

  -- Guards against double-writing a variant within one run.
  unique (run_id, variant_id)
);

create index variant_snapshots_variant_time_idx
  on variant_snapshots(variant_id, observed_at desc);
create index variant_snapshots_site_time_idx
  on variant_snapshots(site_id, observed_at desc);
-- BRIN is the right index for an append-only, time-ordered column: tiny, and
-- effective for the range scans that every trend chart issues.
create index variant_snapshots_observed_brin_idx
  on variant_snapshots using brin(observed_at);
create index variant_snapshots_on_sale_idx
  on variant_snapshots(observed_at desc) where is_on_sale;

-- =============================================================================
-- variant_events — the derived change-log.
--
-- Written by the diff stage by comparing a run against the previous successful
-- run. Everything here is recomputable from variant_snapshots; it exists so the
-- dashboard and any alerting can answer "what changed" without window functions
-- over the full history.
-- =============================================================================
create table variant_events (
  id              bigserial primary key,
  run_id          uuid not null references crawl_runs(id) on delete cascade,
  variant_id      uuid not null references variants(id) on delete cascade,
  site_id         uuid not null references sites(id) on delete cascade,
  event_type      text not null check (event_type in (
                    'listed','delisted',
                    'price_increase','price_decrease',
                    'discount_started','discount_deepened','discount_ended',
                    'went_oos','back_in_stock',
                    'category_added','category_removed'
                  )),
  occurred_at     timestamptz not null default now(),
  old_value       text,
  new_value       text,
  delta_numeric   numeric(12,2),                     -- signed price delta where relevant
  delta_pct       numeric(6,2),
  context         jsonb not null default '{}'::jsonb,
  created_at      timestamptz not null default now()
);

create index variant_events_variant_time_idx on variant_events(variant_id, occurred_at desc);
create index variant_events_site_time_idx on variant_events(site_id, occurred_at desc);
create index variant_events_type_time_idx on variant_events(event_type, occurred_at desc);

-- =============================================================================
-- Scaling note (deliberately not implemented yet — YAGNI)
--
-- At roughly 10M rows, convert variant_snapshots to a monthly-partitioned table:
--
--   create table variant_snapshots (...) partition by range (observed_at);
--   create table variant_snapshots_2026_08
--     partition of variant_snapshots
--     for values from ('2026-08-01') to ('2026-09-01');
--
-- Nothing in the application reads variant_snapshots directly except the
-- pipeline and the views in 0003, so this stays a contained change.
-- =============================================================================

-- >>>>>>>>>>>>>>>>>>>> 20260827000003_views.sql <<<<<<<<<<<<<<<<<<<<
-- =============================================================================
-- 0003_views.sql — the read surface.
--
-- The frontend should query these, never the raw tables. That keeps the
-- "never linearly interpolate", "always filter is_in_assortment" and "latest
-- snapshot per variant" rules in one place instead of in every component.
-- =============================================================================

-- -----------------------------------------------------------------------------
-- Current state of every SKU: newest snapshot, joined through to the canonical
-- model. This is the workhorse for catalogue browsing.
-- -----------------------------------------------------------------------------
create or replace view v_variant_current as
select
  v.id                    as variant_id,
  v.sku,
  v.title                 as variant_title,
  v.core_thickness_mm,
  v.colorway,
  v.shape                 as variant_shape,
  v.attr_confidence,
  pl_player.name          as endorsed_player,

  p.id                    as product_id,
  p.title                 as product_title,
  p.handle,
  p.url                   as product_url,
  p.image_url,
  p.tags,
  p.is_in_assortment,

  m.id                    as model_id,
  m.name                  as model_name,
  m.skill_tier,
  m.shape                 as model_shape,
  line.name               as product_line,
  gen.name                as generation,
  gen.sequence            as generation_sequence,

  s.id                    as site_id,
  b.name                  as brand,
  s.country_code,

  snap.observed_at,
  snap.price,
  snap.compare_at_price,
  snap.currency,
  snap.is_on_sale,
  snap.discount_pct,
  snap.is_available,
  snap.inventory_quantity,

  v.is_active
from variants v
join products p        on p.id = v.product_id
join sites s           on s.id = v.site_id
join brands b          on b.id = s.brand_id
left join models m     on m.id = p.model_id
left join product_lines line on line.id = m.product_line_id
left join generations gen    on gen.id = m.generation_id
left join players pl_player  on pl_player.id = v.endorsed_player_id
-- Newest snapshot per variant. LATERAL keeps this an index seek per variant
-- rather than a sort over the whole history.
left join lateral (
  select vs.observed_at, vs.price, vs.compare_at_price, vs.currency,
         vs.is_on_sale, vs.discount_pct, vs.is_available, vs.inventory_quantity
  from variant_snapshots vs
  where vs.variant_id = v.id
  order by vs.observed_at desc
  limit 1
) snap on true;

-- -----------------------------------------------------------------------------
-- The direct answer to the brief: for each model, how many versions, which
-- thicknesses, which colourways, what price band.
-- -----------------------------------------------------------------------------
create or replace view v_model_overview as
select
  m.id                as model_id,
  b.name              as brand,
  line.name           as product_line,
  gen.name            as generation,
  gen.sequence        as generation_sequence,
  m.name              as model_name,
  m.skill_tier,
  m.shape,
  count(distinct vc.variant_id)                              as sku_count,
  array_agg(distinct vc.core_thickness_mm)
    filter (where vc.core_thickness_mm is not null)          as thicknesses_mm,
  array_agg(distinct vc.colorway)
    filter (where vc.colorway is not null)                   as colorways,
  array_agg(distinct vc.endorsed_player)
    filter (where vc.endorsed_player is not null)            as endorsed_players,
  min(vc.price)                                              as price_min,
  max(vc.price)                                              as price_max,
  count(*) filter (where vc.is_available)                    as skus_in_stock,
  count(*) filter (where vc.is_on_sale)                      as skus_on_sale,
  max(vc.discount_pct)                                       as best_discount_pct,
  vc.currency,
  vc.country_code
from models m
join brands b on b.id = m.brand_id
left join product_lines line on line.id = m.product_line_id
left join generations gen    on gen.id = m.generation_id
join v_variant_current vc    on vc.model_id = m.id
where vc.is_in_assortment
group by m.id, b.name, line.name, gen.name, gen.sequence,
         m.name, m.skill_tier, m.shape, vc.currency, vc.country_code;

-- -----------------------------------------------------------------------------
-- Daily price series. One row per variant per day; where a day has several
-- observations, the last one wins as the close and min/max show the intraday
-- band. Days with no crawl are simply absent — the caller must step-fill, not
-- interpolate (docs/DESIGN.md §6).
-- -----------------------------------------------------------------------------
create or replace view v_variant_price_daily as
select
  vs.variant_id,
  vs.site_id,
  (vs.observed_at at time zone 'UTC')::date          as day,
  min(vs.price)                                      as price_min,
  max(vs.price)                                      as price_max,
  (array_agg(vs.price order by vs.observed_at desc))[1]            as price_close,
  (array_agg(vs.compare_at_price order by vs.observed_at desc))[1] as compare_at_close,
  (array_agg(vs.discount_pct order by vs.observed_at desc))[1]     as discount_pct_close,
  bool_or(vs.is_on_sale)                             as was_on_sale,
  bool_or(vs.is_available)                           as was_available,
  bool_and(vs.is_available)                          as was_always_available,
  count(*)                                           as observations,
  max(vs.currency)                                   as currency
from variant_snapshots vs
group by vs.variant_id, vs.site_id, (vs.observed_at at time zone 'UTC')::date;

-- -----------------------------------------------------------------------------
-- Everything currently discounted, deepest first.
-- -----------------------------------------------------------------------------
create or replace view v_active_discounts as
select
  vc.brand, vc.country_code, vc.product_line, vc.generation, vc.model_name,
  vc.product_title, vc.variant_title, vc.sku, vc.core_thickness_mm, vc.colorway,
  vc.price, vc.compare_at_price, vc.discount_pct, vc.currency,
  vc.is_available, vc.product_url, vc.observed_at
from v_variant_current vc
where vc.is_on_sale and vc.is_in_assortment
order by vc.discount_pct desc;

-- -----------------------------------------------------------------------------
-- Site taxonomy as a breadcrumb list — the captured menu structure.
-- -----------------------------------------------------------------------------
create or replace view v_category_tree as
select
  c.id as category_id, c.site_id, b.name as brand, s.country_code,
  c.handle, c.title, c.category_role, c.depth, c.nav_path, c.in_main_nav,
  c.parent_id, parent.title as parent_title,
  count(pc.product_id) filter (where pc.is_active) as active_products,
  c.is_active
from categories c
join sites s  on s.id = c.site_id
join brands b on b.id = s.brand_id
left join categories parent on parent.id = c.parent_id
left join product_categories pc on pc.category_id = c.id
group by c.id, b.name, s.country_code, parent.title;

-- -----------------------------------------------------------------------------
-- Recent changes feed — what moved, newest first.
-- -----------------------------------------------------------------------------
create or replace view v_recent_changes as
select
  e.id, e.event_type, e.occurred_at, e.old_value, e.new_value,
  e.delta_numeric, e.delta_pct,
  v.sku, v.title as variant_title, v.core_thickness_mm, v.colorway,
  p.title as product_title, p.url as product_url,
  m.name as model_name, m.skill_tier,
  b.name as brand, s.country_code
from variant_events e
join variants v on v.id = e.variant_id
join products p on p.id = v.product_id
join sites s    on s.id = e.site_id
join brands b   on b.id = s.brand_id
left join models m on m.id = p.model_id
order by e.occurred_at desc;

-- >>>>>>>>>>>>>>>>>>>> 20260827000004_rls_and_seed.sql <<<<<<<<<<<<<<<<<<<<
-- =============================================================================
-- 0004_rls_and_seed.sql — access control, then the JOOLA US seed.
-- =============================================================================

-- -----------------------------------------------------------------------------
-- RLS. The ingest runs with the service_role key, which bypasses RLS entirely.
-- Everything else is denied unless a policy grants it. Enabling RLS without
-- adding a permissive policy is the deny-by-default posture we want here: the
-- anon key is safe to ship to a browser because it can read nothing.
--
-- When the dashboard needs direct browser reads, add read-only policies for the
-- `authenticated` role. Until then, the Next.js app should read through a
-- server-side route using the service key.
-- -----------------------------------------------------------------------------
do $$
declare t text;
begin
  foreach t in array array[
    'brands','countries','sites','players','technologies',
    'product_lines','generations','models',
    'categories','products','variants','product_categories',
    'product_content','product_technologies',
    'crawl_runs','crawl_errors','variant_snapshots','variant_events'
  ] loop
    execute format('alter table %I enable row level security', t);
  end loop;
end $$;

-- -----------------------------------------------------------------------------
-- Seed: countries
-- -----------------------------------------------------------------------------
insert into countries (code, name, currency) values
  ('US', 'United States', 'USD'),
  ('IN', 'India',         'INR'),
  ('AU', 'Australia',     'AUD'),
  ('VN', 'Vietnam',       'VND')
on conflict (code) do nothing;

-- -----------------------------------------------------------------------------
-- Seed: JOOLA + its US storefront
--
-- assortment_handles are the collections verified to exist on joola.com and to
-- contain paddles. 'pickleball-paddles' is the parent; the rest are the skill
-- tiers, generations and series that give the taxonomy its shape.
-- -----------------------------------------------------------------------------
insert into brands (slug, name) values ('joola', 'JOOLA')
on conflict (slug) do nothing;

insert into sites (brand_id, country_code, base_url, platform, currency, locale,
                   assortment_handles, crawl_delay_ms, notes)
select
  b.id, 'US', 'https://joola.com', 'shopify', 'USD', 'en-US',
  array[
    'pickleball-paddles',
    'professional-pickleball-paddles',
