-- >>>>>>>>>>>>>>>>>>>> 20260827000005_vocabularies_and_play_style.sql <<<<<<<<<<<<<<<<<<<<
-- =============================================================================
-- 20260827000005 — the last migration that has to be pasted by hand.
--
-- Two jobs:
--
--   1. Add the play-style axis (power / control / hybrid). Selkirk merchandises
--      it as a first-class dimension with dedicated collections and tags; JOOLA
--      does not use it at all, which is why it defaults to 'unknown'.
--
--   2. Replace every brand-vocabulary CHECK constraint with a reference table.
--
-- Job 2 is the important one. CHECK constraints looked tidy while JOOLA was the
-- only brand, but they hardcode one brand's vocabulary into the schema: the
-- moment a brand ships a shape we have not seen, or a tier word we have not
-- met, the fix is a schema migration — DDL, which cannot be applied over the
-- REST API and therefore needs a human pasting SQL into a dashboard.
--
-- A reference table turns that same change into an INSERT. Inserts go over
-- PostgREST with the service key, which means `npm run sync` can do it. After
-- this migration, onboarding a brand touches no SQL at all.
--
-- Integrity is preserved, not traded away: the columns become foreign keys, so
-- an unknown value is still rejected — it just becomes a row we can add from
-- code rather than a constraint we must redeploy.
-- =============================================================================

-- -----------------------------------------------------------------------------
-- 1. Vocabulary reference tables
-- -----------------------------------------------------------------------------
create table if not exists skill_tiers (
  code        text primary key,
  label       text not null,
  sort_order  integer not null default 100,
  notes       text
);

create table if not exists shapes (
  code        text primary key,
  label       text not null,
  sort_order  integer not null default 100,
  notes       text
);

create table if not exists play_styles (
  code        text primary key,
  label       text not null,
  sort_order  integer not null default 100,
  notes       text
);

create table if not exists category_roles (
  code        text primary key,
  label       text not null,
  sort_order  integer not null default 100,
  notes       text
);

-- Current vocabulary. `npm run sync` adds to these as brands introduce words;
-- seeding here only guarantees the foreign keys below can validate today's rows.
insert into skill_tiers (code, label, sort_order) values
  ('pro',          'Pro',           10),
  ('performance',  'Performance',   20),
  ('premium',      'Premium',       30),
  ('recreational', 'Recreational',  40),
  ('junior',       'Junior',        50),
  ('unknown',      'Unknown',      900)
on conflict (code) do nothing;

insert into shapes (code, label, sort_order) values
  ('elongated', 'Elongated',  10),
  ('hybrid',    'Hybrid',     20),
  ('standard',  'Standard',   30),
  ('widebody',  'Widebody',   40),
  ('unknown',   'Unknown',   900)
on conflict (code) do nothing;

insert into play_styles (code, label, sort_order) values
  ('power',   'Power',     10),
  ('control', 'Control',   20),
  ('hybrid',  'Hybrid',    30),
  ('unknown', 'Unknown',  900)
on conflict (code) do nothing;

insert into category_roles (code, label, sort_order) values
  ('sport',      'Sport',        10),
  ('assortment', 'Assortment',   20),
  ('skill_tier', 'Skill tier',   30),
  ('generation', 'Generation',   40),
  ('series',     'Series',       50),
  ('signature',  'Signature',    60),
  ('play_style', 'Play style',   70),
  ('shape',      'Shape',        80),
  ('material',   'Material',     90),
  ('sale',       'Sale',        100),
  ('accessory',  'Accessory',   110),
  ('other',      'Other',       900)
on conflict (code) do nothing;

-- -----------------------------------------------------------------------------
-- 2. play_style on models
--
-- Added before the foreign keys so the new column is covered by them too.
-- -----------------------------------------------------------------------------
alter table models
  add column if not exists play_style text not null default 'unknown';

create index if not exists models_play_style_idx on models(play_style);

-- -----------------------------------------------------------------------------
-- 3. Swap CHECK constraints for foreign keys
--
-- Inline unnamed CHECKs get the name <table>_<column>_check, which is what the
-- drops below target. `if exists` makes this safe whether or not an earlier
-- draft of this migration was already applied.
-- -----------------------------------------------------------------------------
alter table models     drop constraint if exists models_skill_tier_check;
alter table models     drop constraint if exists models_shape_check;
alter table models     drop constraint if exists models_play_style_check;
alter table variants   drop constraint if exists variants_shape_check;
alter table categories drop constraint if exists categories_category_role_check;

-- Any row holding a value outside the seeded vocabulary would block the foreign
-- keys below. There should be none; this repairs rather than aborts if there is.
update models     set skill_tier    = 'unknown' where skill_tier    not in (select code from skill_tiers);
update models     set shape         = 'unknown' where shape         not in (select code from shapes);
update models     set play_style    = 'unknown' where play_style    not in (select code from play_styles);
update variants   set shape         = null      where shape is not null
                                                  and shape not in (select code from shapes);
update categories set category_role = 'other'   where category_role not in (select code from category_roles);

alter table models
  drop constraint if exists models_skill_tier_fkey,
  add constraint models_skill_tier_fkey
    foreign key (skill_tier) references skill_tiers(code) on update cascade;

alter table models
  drop constraint if exists models_shape_fkey,
  add constraint models_shape_fkey
    foreign key (shape) references shapes(code) on update cascade;

alter table models
  drop constraint if exists models_play_style_fkey,
  add constraint models_play_style_fkey
    foreign key (play_style) references play_styles(code) on update cascade;

alter table variants
  drop constraint if exists variants_shape_fkey,
  add constraint variants_shape_fkey
    foreign key (shape) references shapes(code) on update cascade;

alter table categories
  drop constraint if exists categories_category_role_fkey,
  add constraint categories_category_role_fkey
    foreign key (category_role) references category_roles(code) on update cascade;

-- -----------------------------------------------------------------------------
-- 4. Read access to the vocabularies
--
-- RLS is deny-by-default across this schema and the dashboard reads server-side
-- with the service key, so these need no policy to work today. Enabling RLS
-- keeps them consistent with every other table rather than silently readable if
-- an anon key is ever pointed at them.
-- -----------------------------------------------------------------------------
alter table skill_tiers    enable row level security;
alter table shapes         enable row level security;
alter table play_styles    enable row level security;
alter table category_roles enable row level security;

-- =============================================================================
-- 5. Views: surface play_style, weight_grams, shape and brand_slug.
--
-- Rebuilt rather than replaced because CREATE OR REPLACE VIEW cannot insert a
-- column into the middle of a select list. Dropping dependants first keeps the
-- order valid. Views hold no data — this is not a destructive operation, though
-- the SQL editor's guard will ask you to confirm it.
-- =============================================================================
drop view if exists v_active_discounts;
drop view if exists v_model_overview;
drop view if exists v_variant_current;

create view v_variant_current as
select
  v.id                    as variant_id,
  v.sku,
  v.title                 as variant_title,
  v.core_thickness_mm,
  v.colorway,
  v.weight_grams,
  v.shape                 as variant_shape,
  v.attr_confidence,
  pl_player.name          as endorsed_player,

  p.id                    as product_id,
  p.title                 as product_title,
  p.handle,
  p.url                   as product_url,
  p.image_url,
  p.tags,
  p.is_in_assortment,

  m.id                    as model_id,
  m.name                  as model_name,
  m.skill_tier,
  m.play_style,
  m.shape                 as model_shape,
  line.name               as product_line,
  gen.name                as generation,
  gen.sequence            as generation_sequence,

  s.id                    as site_id,
  b.name                  as brand,
  b.slug                  as brand_slug,
  s.country_code,

  snap.observed_at,
  snap.price,
  snap.compare_at_price,
  snap.currency,
  snap.is_on_sale,
  snap.discount_pct,
  snap.is_available,
  snap.inventory_quantity,

  v.is_active
from variants v
join products p        on p.id = v.product_id
join sites s           on s.id = v.site_id
join brands b          on b.id = s.brand_id
left join models m     on m.id = p.model_id
left join product_lines line on line.id = m.product_line_id
left join generations gen    on gen.id = m.generation_id
left join players pl_player  on pl_player.id = v.endorsed_player_id
left join lateral (
  select vs.observed_at, vs.price, vs.compare_at_price, vs.currency,
         vs.is_on_sale, vs.discount_pct, vs.is_available, vs.inventory_quantity
  from variant_snapshots vs
  where vs.variant_id = v.id
  order by vs.observed_at desc
  limit 1
) snap on true;

create view v_model_overview as
select
  m.id                as model_id,
  b.name              as brand,
  b.slug              as brand_slug,
  line.name           as product_line,
  gen.name            as generation,
  gen.sequence        as generation_sequence,
  m.name              as model_name,
  m.skill_tier,
  m.play_style,
  m.shape,
  count(distinct vc.variant_id)                              as sku_count,
  array_agg(distinct vc.core_thickness_mm)
    filter (where vc.core_thickness_mm is not null)          as thicknesses_mm,
  array_agg(distinct vc.colorway)
    filter (where vc.colorway is not null)                   as colorways,
  array_agg(distinct vc.variant_shape)
    filter (where vc.variant_shape is not null
            and vc.variant_shape <> 'unknown')               as shapes,
  array_agg(distinct vc.endorsed_player)
    filter (where vc.endorsed_player is not null)            as endorsed_players,
  min(vc.price)                                              as price_min,
  max(vc.price)                                              as price_max,
  count(*) filter (where vc.is_available)                    as skus_in_stock,
  count(*) filter (where vc.is_on_sale)                      as skus_on_sale,
  max(vc.discount_pct)                                       as best_discount_pct,
  vc.currency,
  vc.country_code
from models m
join brands b on b.id = m.brand_id
left join product_lines line on line.id = m.product_line_id
left join generations gen    on gen.id = m.generation_id
join v_variant_current vc    on vc.model_id = m.id
where vc.is_in_assortment
group by m.id, b.name, b.slug, line.name, gen.name, gen.sequence,
         m.name, m.skill_tier, m.play_style, m.shape, vc.currency, vc.country_code;

create view v_active_discounts as
select
  vc.brand, vc.brand_slug, vc.country_code, vc.product_line, vc.generation,
  vc.model_name, vc.product_title, vc.variant_title, vc.sku,
  vc.core_thickness_mm, vc.colorway,
  vc.price, vc.compare_at_price, vc.discount_pct, vc.currency,
  vc.is_available, vc.product_url, vc.observed_at
from v_variant_current vc
where vc.is_on_sale and vc.is_in_assortment
order by vc.discount_pct desc;

-- The change feed gains brand_slug so the dashboard can filter without a join.
--
-- Dropped first, like the three above. CREATE OR REPLACE VIEW can only append
-- columns to the end of the select list; brand_slug belongs next to brand, and
-- inserting it there is a rename as far as Postgres is concerned:
--   ERROR 42P16: cannot change name of view column "country_code" to "brand_slug"
drop view if exists v_recent_changes;

create view v_recent_changes as
select
  e.id, e.event_type, e.occurred_at, e.old_value, e.new_value,
  e.delta_numeric, e.delta_pct,
  v.sku, v.title as variant_title, v.core_thickness_mm, v.colorway,
  p.title as product_title, p.url as product_url,
  m.name as model_name, m.skill_tier,
  b.name as brand, b.slug as brand_slug, s.country_code
from variant_events e
join variants v on v.id = e.variant_id
join products p on p.id = v.product_id
join sites s    on s.id = e.site_id
join brands b   on b.id = s.brand_id
left join models m on m.id = p.model_id
order by e.occurred_at desc;

-- =============================================================================
-- Deliberately NOT here: the Selkirk brand, site and product lines.
--
-- Those are data, not schema. An earlier draft of this migration seeded them in
-- SQL, which is what made every new brand look like it needed a migration. They
-- now live in src/config/ and are pushed by `npm run sync`, so brand #3 is a
-- TypeScript file and a command — no dashboard, no paste.
-- =============================================================================

-- >>>>>>>>>>>>>>>>>>>> 20260828000001_reviews.sql <<<<<<<<<<<<<<<<<<<<
-- =============================================================================
-- 0006_reviews.sql — customer reviews, brand replies, and their time series
--
-- Three layers, mirroring the rest of the schema:
--
--   reviews                   what a customer wrote      (upserted, carries seen-dates)
--   review_responses          what the brand wrote back  (upserted, the reply chain)
--   product_review_snapshots  what the shelf looked like (append-only, one row per run)
--
-- Why a review needs BOTH an upsert table and a snapshot table:
--
-- A review is not a price. Its text is written once and rarely changes, so
-- re-inserting it every run would multiply one customer's opinion by the number
-- of times we happened to look. But the things *around* it do move — helpful
-- counts climb, the brand replies a week later, and the product's average drifts
-- as new reviews land. So the review itself is upserted on its source id and
-- carries first_seen_at / last_seen_at, while the aggregate that actually moves
-- is snapshotted per run. That is what makes "how did sentiment move over the
-- last six months" a range scan rather than an archaeology project.
--
-- Every brand runs a different review platform (Bazaarvoice / Okendo /
-- Judge.me), so review_platform is carried on the row and the source id is only
-- unique within it. See docs/REVIEWS_RESEARCH.md.
-- =============================================================================

-- Which review platform a storefront runs, and what the adapter needs to reach
-- it (Bazaarvoice client + displayCode, Okendo subscriberId, Judge.me shop
-- domain). Config, not schema — so brand #4 stays a config change.
alter table sites add column if not exists review_platform text;
alter table sites add column if not exists review_config jsonb not null default '{}'::jsonb;

-- Run counters for the reviews stage. finaliseRun() writes the whole RunStats
-- object onto the run row, so every stat needs a column here or the update is
-- rejected and the run never leaves 'running'.
alter table crawl_runs add column if not exists reviews_found integer not null default 0;
alter table crawl_runs add column if not exists reviews_new integer not null default 0;
alter table crawl_runs add column if not exists review_responses_new integer not null default 0;

-- product_technologies was the one scraped table carrying no date at all, so a
-- technology claim appearing on or disappearing from a product was invisible.
-- Brought in line with product_categories, which models the same kind of
-- membership-over-time relationship.
alter table product_technologies add column if not exists first_seen_at timestamptz not null default now();
alter table product_technologies add column if not exists last_seen_at  timestamptz not null default now();
alter table product_technologies add column if not exists is_active     boolean not null default true;

-- =============================================================================
-- reviews — one row per customer review, ever.
-- =============================================================================
create table if not exists reviews (
  id                  uuid primary key default gen_random_uuid(),
  site_id             uuid not null references sites(id) on delete cascade,
  product_id          uuid not null references products(id) on delete cascade,

  -- Provenance. Source ids collide across platforms, so the platform is part
  -- of the natural key rather than an attribute hanging off it.
  review_platform     text not null,                 -- bazaarvoice | okendo | judgeme
  source_review_id    text not null,

  -- Content.
  rating              numeric(3,2),                  -- numeric: Okendo can emit halves
  rating_range        integer not null default 5,
  title               text,
  body                text,
  pros                text,
  cons                text,

  -- Author. Display name only — whatever the storefront already shows in public.
  author_name         text,
  author_id           text,
  author_location     text,

  -- Flags a reader filters on.
  is_verified_buyer   boolean,
  is_recommended      boolean,
  is_incentivized     boolean,
  is_syndicated       boolean,
  -- A star with no words. 84 of JOOLA's first 120 are these; they must count
  -- toward the average but must never surface as an empty card in a text search.
  is_ratings_only     boolean not null default false,

  -- Engagement. Current values, refreshed each run.
  helpful_count       integer not null default 0,
  unhelpful_count     integer not null default 0,
  response_count      integer not null default 0,
  photo_count         integer not null default 0,
  video_count         integer not null default 0,

  -- Which SKU the reviewer actually bought, when the platform says so.
  variant_label       text,
  source_variant_id   text,

  -- Platform-specific structured extras, kept whole rather than flattened:
  -- Bazaarvoice Age / Gender / LengthOfOwnership, secondary ratings, badges.
  -- This is the raw material for the sentiment and complaint analysis that will
  -- sit on top of this table later.
  context_data        jsonb not null default '{}'::jsonb,
  media               jsonb not null default '[]'::jsonb,

  -- === Time ==================================================================
  -- submitted_at is when the CUSTOMER wrote it.
  submitted_at        timestamptz,
  source_updated_at   timestamptz,
  -- first_seen_at / last_seen_at are when WE looked. The gap between
  -- submitted_at and first_seen_at is our own collection lag, and keeping both
  -- is what lets a weekly cadence still plot reviews on the day they were left.
  first_seen_at       timestamptz not null default now(),
  last_seen_at        timestamptz not null default now(),
  first_seen_run_id   uuid references crawl_runs(id) on delete set null,
  last_seen_run_id    uuid references crawl_runs(id) on delete set null,

  language_code       text,

  -- Full-text search vector. Generated and stored so the /reviews search is an
  -- index scan rather than a scan-and-tokenise over every row. Title is weighted
  -- above body so "cracked" in a headline outranks it in a paragraph.
  search_tsv          tsvector generated always as (
                        setweight(to_tsvector('english', coalesce(title, '')), 'A') ||
                        setweight(to_tsvector('english', coalesce(body,  '')), 'B') ||
                        setweight(to_tsvector('english', coalesce(pros,  '')), 'C') ||
                        setweight(to_tsvector('english', coalesce(cons,  '')), 'C')
                      ) stored,

  unique (site_id, review_platform, source_review_id)
);

create index if not exists reviews_product_idx    on reviews(product_id);
create index if not exists reviews_site_idx       on reviews(site_id);
-- The default sort of the reviews page.
create index if not exists reviews_submitted_idx  on reviews(submitted_at desc nulls last);
create index if not exists reviews_rating_idx     on reviews(rating);
create index if not exists reviews_first_seen_idx on reviews(first_seen_at desc);
create index if not exists reviews_search_idx     on reviews using gin(search_tsv);
-- Trigram index backs the substring fallback for queries full-text stems away —
-- a model number, a part name, a two-letter brand.
create index if not exists reviews_body_trgm_idx  on reviews using gin(body gin_trgm_ops);
-- Partial index: "show me the complaints" is the most expensive common query.
create index if not exists reviews_low_rating_idx
  on reviews(site_id, submitted_at desc) where rating <= 3;

-- =============================================================================
-- review_responses — the reply chain.
--
-- Bazaarvoice returns these as ClientResponses[] with no stable id, Judge.me as
-- an inline reply block, Okendo as a comment. None of them guarantee an id, so
-- the dedupe key is a hash of the response body: replies are edited rarely, and
-- an edited reply is genuinely a new thing to have seen.
-- =============================================================================
create table if not exists review_responses (
  id                  uuid primary key default gen_random_uuid(),
  review_id           uuid not null references reviews(id) on delete cascade,
  site_id             uuid not null references sites(id) on delete cascade,

  source_response_id  text,
  response_hash       text not null,                 -- sha256 of the normalised body

  author_name         text,
  department          text,                          -- 'Team JOOLA'
  response_source     text,                          -- 'mc-api'
  body                text not null,

  responded_at        timestamptz,
  first_seen_at       timestamptz not null default now(),
  last_seen_at        timestamptz not null default now(),
  first_seen_run_id   uuid references crawl_runs(id) on delete set null,

  unique (review_id, response_hash)
);

create index if not exists review_responses_review_idx on review_responses(review_id);
create index if not exists review_responses_site_time_idx
  on review_responses(site_id, responded_at desc);

-- =============================================================================
-- product_review_snapshots — append-only, one row per product per run.
--
-- This is the series that answers the question the feature exists for: how is a
-- product's reception changing over months and years. Deliberately denormalised
-- into star buckets so a distribution chart is one row, not a group-by over
-- every review ever written.
-- =============================================================================
create table if not exists product_review_snapshots (
  id                    bigserial primary key,
  run_id                uuid not null references crawl_runs(id) on delete cascade,
  product_id            uuid not null references products(id) on delete cascade,
  site_id               uuid not null references sites(id) on delete cascade,
  observed_at           timestamptz not null default now(),

  -- What the platform itself claims its total is, when it exposes one. Kept
  -- apart from our own count so a truncated crawl is visible rather than silent.
  reported_total        integer,

  review_count          integer not null default 0,  -- rows we hold for this product
  with_text_count       integer not null default 0,
  ratings_only_count    integer not null default 0,
  average_rating        numeric(4,3),

  rating_1_count        integer not null default 0,
  rating_2_count        integer not null default 0,
  rating_3_count        integer not null default 0,
  rating_4_count        integer not null default 0,
  rating_5_count        integer not null default 0,

  recommended_count     integer not null default 0,
  not_recommended_count integer not null default 0,
  verified_count        integer not null default 0,
  with_response_count   integer not null default 0,

  -- Reviews whose first_seen_run_id is this run: the arrival rate, which leads
  -- the average. A drop to zero on a product that averaged ten a week is worth
  -- knowing well before the average itself moves.
  new_review_count      integer not null default 0,

  unique (run_id, product_id)
);

create index if not exists product_review_snapshots_product_time_idx
  on product_review_snapshots(product_id, observed_at desc);
create index if not exists product_review_snapshots_site_time_idx
  on product_review_snapshots(site_id, observed_at desc);
create index if not exists product_review_snapshots_observed_brin_idx
  on product_review_snapshots using brin(observed_at);

-- =============================================================================
-- Views
-- =============================================================================
drop view if exists v_review_search;
drop view if exists v_product_reviews_current;

-- One row per review, pre-joined to everything the search page filters on, so
-- the UI never fans out joins per row.
create view v_review_search as
select
  r.id                as review_id,
  r.review_platform,
  r.source_review_id,
  r.rating,
  r.rating_range,
  r.title,
  r.body,
  r.pros,
  r.cons,
  r.author_name,
  r.author_location,
  r.is_verified_buyer,
  r.is_recommended,
  r.is_incentivized,
  r.is_ratings_only,
  r.helpful_count,
  r.unhelpful_count,
  r.response_count,
  r.photo_count,
  r.variant_label,
  r.context_data,
  r.media,
  r.submitted_at,
  r.first_seen_at,
  r.last_seen_at,

  p.id                as product_id,
  p.title             as product_title,
  p.handle            as product_handle,
  p.url               as product_url,
  p.image_url         as product_image_url,
  p.is_in_assortment,

  m.id                as model_id,
  m.name              as model_name,
  m.skill_tier,
  m.play_style,
  line.name           as product_line,
  gen.name            as generation,

  s.id                as site_id,
  s.country_code,
  b.name              as brand,
  b.slug              as brand_slug
from reviews r
join products p on p.id = r.product_id
join sites s    on s.id = r.site_id
join brands b   on b.id = s.brand_id
left join models m           on m.id = p.model_id
left join product_lines line on line.id = m.product_line_id
left join generations gen    on gen.id = m.generation_id;

-- Latest review standing per product — the aggregate the catalogue and model
-- pages show next to price.
create view v_product_reviews_current as
select
  p.id                as product_id,
  p.title             as product_title,
  p.handle,
  p.model_id,
  s.id                as site_id,
  b.name              as brand,
  b.slug              as brand_slug,
  snap.observed_at,
  snap.reported_total,
  snap.review_count,
  snap.with_text_count,
  snap.average_rating,
  snap.rating_1_count,
  snap.rating_2_count,
  snap.rating_3_count,
  snap.rating_4_count,
  snap.rating_5_count,
  snap.recommended_count,
  snap.not_recommended_count,
  snap.verified_count,
  snap.with_response_count,
  snap.new_review_count
from products p
join sites s  on s.id = p.site_id
join brands b on b.id = s.brand_id
left join lateral (
  select *
  from product_review_snapshots prs
  where prs.product_id = p.id
  order by prs.observed_at desc
  limit 1
) snap on true;

-- =============================================================================
-- RLS. Same posture as the rest of the schema: service_role writes, anon reads.
-- =============================================================================
alter table reviews                  enable row level security;
alter table review_responses         enable row level security;
alter table product_review_snapshots enable row level security;

drop policy if exists reviews_read                  on reviews;
drop policy if exists review_responses_read         on review_responses;
drop policy if exists product_review_snapshots_read on product_review_snapshots;

create policy reviews_read                  on reviews                  for select using (true);
create policy review_responses_read         on review_responses         for select using (true);
create policy product_review_snapshots_read on product_review_snapshots for select using (true);

